import { createCanvas, loadImage, type Canvas, type SKRSContext2D } from '@napi-rs/canvas';
import { drawSceneOverlay, type FrameScene, type FrameStyle } from './drawing';
import type { WordTiming } from './voice';

// The 'realista' visual style: each scene is a photo (image_url, generated by
// the web app into the scene-images bucket) animated with a slow Ken Burns
// move, with the same subtitles, counter and edge fades as a drawn scene.
// Nothing here can fail a render: a photo that is missing, untrusted or
// undecodable makes the caller draw that scene the illustrated way instead.

const DOWNLOAD_TIMEOUT_MS = Math.max(1000, Number(process.env.SCENE_IMAGE_TIMEOUT_MS ?? 20_000));
// Generous for a 1080x1920 JPEG/PNG (usually 0.3-3 MB), small enough that a
// wrong URL cannot pull a huge file into memory - the job's disk is RAM too.
const MAX_DOWNLOAD_BYTES = 15 * 1024 * 1024;
// Checked from the file header BEFORE decoding: a decoded bitmap costs 4 bytes
// per pixel whatever the file size, so a 15 MB JPEG of 100 megapixels would
// still be a 400 MB allocation. 40 MP (160 MB transient) covers any real photo.
const MAX_PIXELS = 40_000_000;
const MAX_SIDE = 12_000;

// The move: zoom 1.00 -> 1.08 (or back) on top of a fixed 4% overscan, so the
// pan has room even at zoom 1.00 and never exposes an edge.
const ZOOM_SPAN = 0.08;
const OVERSCAN = 1.04;
// The photo is resampled once per scene into a canvas this much larger than
// the frame: at the closest zoom one source pixel is then one output pixel, so
// the move never upsamples, and every frame is a cheap crop-and-scale.
const SOURCE_SCALE = (1 + ZOOM_SPAN) * OVERSCAN;

// Directions per scene, cycled by scene index so consecutive photos never
// move the same way. Pan values are fractions (-1..1) of the margin available
// at each instant's zoom, so a pan can never run past the photo's edge.
interface KenBurnsProfile { zoomIn: boolean; panXFrom: number; panXTo: number; panYFrom: number; panYTo: number }

const KEN_BURNS_PROFILES: KenBurnsProfile[] = [
	{ zoomIn: true, panXFrom: -0.6, panXTo: 0.6, panYFrom: 0.2, panYTo: -0.2 },
	{ zoomIn: false, panXFrom: 0.6, panXTo: -0.6, panYFrom: -0.3, panYTo: 0.3 },
	{ zoomIn: true, panXFrom: 0, panXTo: 0, panYFrom: 0.7, panYTo: -0.7 },
	{ zoomIn: false, panXFrom: -0.5, panXTo: 0.5, panYFrom: -0.6, panYTo: 0.6 },
];

// Sine ease-in-out: starts and ends at rest, gentler in the middle than a
// cubic, which is what keeps a photo move reading as "camera", not "effect".
function easeSine(t: number) {
	return 0.5 - 0.5 * Math.cos(Math.PI * Math.min(1, Math.max(0, t)));
}

/** A reusable surface a scene's photo is resampled into (see loadScenePhoto). */
export function createPhotoCanvas(width: number, height: number): Canvas {
	return createCanvas(Math.ceil(width * SOURCE_SCALE), Math.ceil(height * SOURCE_SCALE));
}

// Only photos the web app itself stored in this project's public scene-images
// bucket are fetched: the URL comes from the job body, and the worker would
// otherwise fetch anything (other hosts, internal addresses). Same rule as the
// branding logo. Outside production, http://127.0.0.1 is also accepted so the
// path can be exercised against a local file server; the job image sets
// NODE_ENV=production, so that never applies in Cloud Run.
export function trustedSceneImageUrl(raw: string, supabaseUrl: string | undefined): string | null {
	let parsed: URL;
	try {
		// new URL() resolves dot segments, so "<prefix>../other-bucket/x"
		// cannot pass the prefix test and still escape the bucket.
		parsed = new URL(raw);
	} catch {
		return null;
	}
	if (process.env.NODE_ENV !== 'production' && parsed.protocol === 'http:' && parsed.hostname === '127.0.0.1') {
		return parsed.href;
	}
	if (!supabaseUrl || parsed.protocol !== 'https:') return null;
	const prefix = `${supabaseUrl.replace(/\/+$/, '')}/storage/v1/object/public/scene-images/`;
	return parsed.href.startsWith(prefix) ? parsed.href : null;
}

async function downloadCapped(url: string): Promise<Buffer> {
	// redirect 'error': a redirect would take the request off the trusted
	// bucket the URL was checked against.
	const response = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS) });
	if (!response.ok || !response.body) throw new Error(`La imagen respondio HTTP ${response.status}.`);
	const declared = Number(response.headers.get('content-length'));
	if (Number.isFinite(declared) && declared > MAX_DOWNLOAD_BYTES) {
		await response.body.cancel().catch(() => undefined);
		throw new Error(`La imagen pesa ${declared} bytes (maximo ${MAX_DOWNLOAD_BYTES}).`);
	}
	const chunks: Uint8Array[] = [];
	let total = 0;
	const reader = response.body.getReader();
	for (;;) {
		const { done, value } = await reader.read();
		if (done) break;
		total += value.byteLength;
		if (total > MAX_DOWNLOAD_BYTES) {
			await reader.cancel().catch(() => undefined);
			throw new Error(`La imagen supera el maximo de ${MAX_DOWNLOAD_BYTES} bytes.`);
		}
		chunks.push(value);
	}
	return Buffer.concat(chunks, total);
}

// Width and height from the PNG or JPEG header, without decoding. Anything
// that is neither format is refused here, before the decoder ever sees it.
function imageDimensions(bytes: Buffer): { width: number; height: number } {
	if (bytes.length >= 24 && bytes.readUInt32BE(0) === 0x89504e47 && bytes.toString('ascii', 12, 16) === 'IHDR') {
		return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) };
	}
	if (bytes.length >= 4 && bytes[0] === 0xff && bytes[1] === 0xd8) {
		let offset = 2;
		while (offset + 9 < bytes.length) {
			if (bytes[offset] !== 0xff) { offset += 1; continue; }
			const marker = bytes[offset + 1];
			// Fill bytes and markers without a length field.
			if (marker === 0xff || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd9)) { offset += 2; continue; }
			const length = bytes.readUInt16BE(offset + 2);
			// SOF0..SOF15, except DHT (C4), JPG (C8) and DAC (CC).
			if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
				return { width: bytes.readUInt16BE(offset + 7), height: bytes.readUInt16BE(offset + 5) };
			}
			offset += 2 + length;
		}
		throw new Error('JPEG sin cabecera de tamano legible.');
	}
	throw new Error('La imagen no es JPEG ni PNG.');
}

/**
 * Downloads a scene photo and resamples it, cover-fitted, into `target` (a
 * canvas from createPhotoCanvas). The decoded image only lives inside this
 * call: what the scene's frames read afterwards is the reused target surface,
 * so a render holds at most two photo surfaces however many scenes it has.
 * Throws on any failure; the caller falls back to the drawn scene.
 */
export async function loadScenePhoto(url: string, target: Canvas): Promise<void> {
	const bytes = await downloadCapped(url);
	const { width, height } = imageDimensions(bytes);
	if (width < 1 || height < 1 || width > MAX_SIDE || height > MAX_SIDE || width * height > MAX_PIXELS) {
		throw new Error(`Tamano de imagen no admitido: ${width}x${height}.`);
	}
	const image = await loadImage(bytes);
	if (!image.width || !image.height) throw new Error('La imagen no se pudo decodificar.');

	const ctx = target.getContext('2d');
	const scale = Math.max(target.width / image.width, target.height / image.height);
	const drawWidth = image.width * scale;
	const drawHeight = image.height * scale;
	ctx.imageSmoothingEnabled = true;
	// One resample per scene, so the best filter is affordable here; the
	// per-frame crop below scales by at most ~12% and stays on the default.
	ctx.imageSmoothingQuality = 'high';
	ctx.fillStyle = '#000000';
	ctx.fillRect(0, 0, target.width, target.height);
	ctx.drawImage(image, (target.width - drawWidth) / 2, (target.height - drawHeight) / 2, drawWidth, drawHeight);
}

// Darkened edges and a darker bottom third: the photo is arbitrary, and the
// subtitle panel alone was not enough over a bright sky or a white wall.
function drawPhotoShade(ctx: SKRSContext2D, width: number, height: number) {
	const vignette = ctx.createRadialGradient(width / 2, height * 0.45, Math.min(width, height) * 0.35, width / 2, height * 0.45, Math.hypot(width, height) * 0.6);
	vignette.addColorStop(0, 'rgba(0,0,0,0)');
	vignette.addColorStop(1, 'rgba(0,0,0,0.38)');
	ctx.fillStyle = vignette;
	ctx.fillRect(0, 0, width, height);

	const bottom = ctx.createLinearGradient(0, height * 0.55, 0, height);
	bottom.addColorStop(0, 'rgba(0,0,0,0)');
	bottom.addColorStop(1, 'rgba(0,0,0,0.6)');
	ctx.fillStyle = bottom;
	ctx.fillRect(0, height * 0.55, width, height * 0.45);
}

/**
 * One frame of a photo scene: the Ken Burns crop of `photo` (prepared by
 * loadScenePhoto), the shade, then the same overlay a drawn scene gets. Same
 * arguments as drawSceneFrame minus the mouth: there is no character here.
 */
export function drawPhotoSceneFrame(
	ctx: SKRSContext2D,
	photo: Canvas,
	scene: FrameScene,
	t: number,
	duration: number,
	style: FrameStyle,
	wordTimings: WordTiming[] | null = null,
	fadeEdges: { in: boolean; out: boolean } | null = null,
) {
	const { width, height } = style;
	const profile = KEN_BURNS_PROFILES[scene.index % KEN_BURNS_PROFILES.length];
	const eased = easeSine(duration > 0 ? t / duration : 0);
	const zoom = 1 + ZOOM_SPAN * (profile.zoomIn ? eased : 1 - eased);
	const panX = profile.panXFrom + (profile.panXTo - profile.panXFrom) * eased;
	const panY = profile.panYFrom + (profile.panYTo - profile.panYFrom) * eased;

	// The visible part of the source at this zoom, centred and then pushed
	// by the pan fraction of whatever margin is left around it.
	// At the closest zoom this is exactly width x height source pixels.
	const cropWidth = (width * SOURCE_SCALE) / (zoom * OVERSCAN);
	const cropHeight = (height * SOURCE_SCALE) / (zoom * OVERSCAN);
	const marginX = (photo.width - cropWidth) / 2;
	const marginY = (photo.height - cropHeight) / 2;
	const sourceX = marginX + panX * marginX;
	const sourceY = marginY + panY * marginY;

	ctx.drawImage(photo, sourceX, sourceY, cropWidth, cropHeight, 0, 0, width, height);
	drawPhotoShade(ctx, width, height);
	drawSceneOverlay(ctx, scene, t, duration, style, wordTimings, fadeEdges);
}
